import json
import subprocess
import sys

from layout_overlap import get_layout, find_overlaps

TEMPLATE = r'''// SPDX-License-Identifier: MIT
// AUTO-GENERATED by analysis/generate.py - do not edit by hand
pragma solidity ^0.8.20;

import {Test, console} from "forge-std/Test.sol";
import {VmSafe} from "forge-std/Vm.sol";
@@IMPORTS@@

contract GeneratedTest is Test {
    address proxy;
    address[3] callers;

    mapping(bytes32 => mapping(uint8 => address)) internal owner;
    uint256 internal collisions;

    uint256 constant NUM_ACTIONS = @@N@@;
    uint256 constant PROBES = 40;
    uint256 constant BOOST = 20;
    uint256[@@N@@] internal weights;
    uint256 internal totalWeight;

    function _deploy() internal returns (address p, address l) {
        @@DEPLOY@@
    }

    function setUp() public {
        callers = [address(0xA11CE), address(0xBAD), address(0xCAFE)];
        (proxy, ) = _deploy();
        _buildWeights();
    }

    // ---------- argument generation ----------
    function _u(uint256 s, uint256 i) internal pure returns (uint256) {
        uint256 h = uint256(keccak256(abi.encode(s, i)));
        uint256 k = h % 5;
        if (k == 0) return 0;
        if (k == 1) return 1;
        if (k == 2) return 2;
        if (k == 3) return type(uint256).max;
        return h >> 8;
    }

    function _addr(uint256 s, uint256 i) internal view returns (address) {
        //return callers[uint256(keccak256(abi.encode(s, i, "a"))) % 3];
        uint256 k = uint256(keccak256(abi.encode(s, i, "a"))) % 4;
        if (k == 3) return address(0);
        return callers[k];
    }

    // ---------- generated: one branch per state-changing function ----------
    function _encodeAction(uint256 a, uint256 s) internal view returns (bytes memory) {
@@ENCODE@@
        revert("bad action");
    }

    // ---------- generated: byte positions where proxy and logic layouts overlap ----------
    function _inOverlap(uint256 pos) internal pure returns (bool) {
        return @@OVERLAP@@;
    }

    // ---------- ownership oracle ----------
    function _call(address caller, bytes memory data) internal {
        vm.startStateDiffRecording();
        vm.prank(caller);
        proxy.call(data);
        VmSafe.AccountAccess[] memory accesses = vm.stopAndReturnStateDiff();
        _checkOwnership(accesses);
    }

    function _checkOwnership(VmSafe.AccountAccess[] memory accesses) internal {
        for (uint256 i = 0; i < accesses.length; i++) {
            address writer = accesses[i].account;
            VmSafe.StorageAccess[] memory sa = accesses[i].storageAccesses;
            for (uint256 j = 0; j < sa.length; j++) {
                if (!sa[j].isWrite || sa[j].reverted) continue;
                if (sa[j].account != proxy) continue;
                uint256 diff = uint256(sa[j].previousValue ^ sa[j].newValue);
                for (uint256 b = 0; b < 32; b++) {
                    if (((diff >> (8 * b)) & 0xff) == 0) continue;
                    address current = owner[sa[j].slot][uint8(b)];
                    if (current == address(0)) {
                        owner[sa[j].slot][uint8(b)] = writer;
                    } else if (current != writer) {
                        collisions++;
                        console.log("COLLISION at slot", uint256(sa[j].slot));
                        console.log("  byte offset", b);
                        console.log("  owner :", current);
                        console.log("  writer:", writer);
                    }
                }
            }
        }
    }

    // ---------- guidance ----------
    function _touchesOverlap(VmSafe.AccountAccess[] memory acc, address p) internal pure returns (bool) {
        for (uint256 i = 0; i < acc.length; i++) {
            VmSafe.StorageAccess[] memory sa = acc[i].storageAccesses;
            for (uint256 j = 0; j < sa.length; j++) {
                if (!sa[j].isWrite || sa[j].reverted || sa[j].account != p) continue;
                if (uint256(sa[j].slot) > 2 ** 200) continue; // hashed slots
                uint256 diff = uint256(sa[j].previousValue ^ sa[j].newValue);
                for (uint256 b = 0; b < 32; b++) {
                    if (((diff >> (8 * b)) & 0xff) == 0) continue;
                    if (_inOverlap(uint256(sa[j].slot) * 32 + b)) return true;
                }
            }
        }
        return false;
    }

    function _probe(uint256 a) internal returns (bool) {
       // for (uint256 k = 0; k < PROBES; k++) {
       //     uint256 s = uint256(keccak256(abi.encode("probe", a, k)));
         //   bytes memory data = _encodeAction(a, s);
           // (address p, ) = _deploy();
            //vm.startStateDiffRecording();
            //vm.prank(callers[0]);
            //p.call(data);
            //VmSafe.AccountAccess[] memory acc = vm.stopAndReturnStateDiff();
         //   if (_touchesOverlap(acc, p)) return true;
        //}
        //return false;
        for (uint256 k = 0; k < PROBES; k++) {
            (address p, ) = _deploy();

            // random prefix of 0..3 actions, so prerequisite state can exist
            uint256 plen = k % 4;
            for (uint256 i = 0; i < plen; i++) {
                uint256 ps = uint256(keccak256(abi.encode("prefix", a, k, i)));
                uint256 pa = ps % NUM_ACTIONS;
                address pc = callers[uint256(keccak256(abi.encode(ps, "c"))) % 3];
                vm.prank(pc);
                p.call(_encodeAction(pa, ps));
            }

            // the probed action, from a random caller
            uint256 s = uint256(keccak256(abi.encode("probe", a, k)));
            address caller = callers[uint256(keccak256(abi.encode(s, "caller"))) % 3];
            bytes memory data = _encodeAction(a, s);
            vm.startStateDiffRecording();
            vm.prank(caller);
            p.call(data);
            VmSafe.AccountAccess[] memory acc = vm.stopAndReturnStateDiff();
            if (_touchesOverlap(acc, p)) return true;
        }
        return false;
    }

    function _buildWeights() internal {
        for (uint256 a = 0; a < NUM_ACTIONS; a++) {
            weights[a] = _probe(a) ? BOOST : 1;
            totalWeight += weights[a];
            console.log("action", a, "weight", weights[a]);
        }
    }

    function _pick(uint256 r) internal view returns (uint256) {
        uint256 x = r % totalWeight;
        for (uint256 a = 0; a < NUM_ACTIONS; a++) {
            if (x < weights[a]) return a;
            x -= weights[a];
        }
        return 0;
    }

    // ---------- fuzz entry points ----------
    function _runSequence(uint256 seed, bool guided) internal {
        for (uint256 i = 0; i < 6; i++) {
            seed = uint256(keccak256(abi.encode(seed, i)));
            address caller = callers[seed % 3];
            uint256 r = uint256(keccak256(abi.encode(seed, "pick")));
            uint256 a = guided ? _pick(r) : r % NUM_ACTIONS;
            _call(caller, _encodeAction(a, seed));
        }
    }

    function testFuzz_random_sequence(uint256 seed) public {
        _runSequence(seed, false);
        assertEq(collisions, 0, "storage collision found");
    }

    function testFuzz_guided_sequence(uint256 seed) public {
        _runSequence(seed, true);
        assertEq(collisions, 0, "storage collision found");
    }
}
'''


def forge_inspect(contract, what):
    out = subprocess.run(
        ["forge", "inspect", contract, what, "--json"],
        capture_output=True, text=True, check=True,
    ).stdout
    data = json.loads(out)
    return data.get("abi", []) if isinstance(data, dict) else data


def arg_expr(t, i):
    u = f"_u(s, {i})"
    if "[" in t or t in ("bytes", "string") or t.startswith("tuple"):
        return None  # unsupported for now
    if t.startswith("uint"):
        return f"{t}({u})"
    if t.startswith("int"):
        return f"{t}(int256({u}))"
    if t == "address":
        return f"_addr(s, {i})"
    if t == "bool":
        return f"((({u}) & 1) == 1)"
    if t.startswith("bytes"):
        return f"{t}(bytes32({u}))"
    return None


def collect_actions(contracts):
    actions, skipped, seen = [], [], set()
    for c in contracts:
        for e in forge_inspect(c, "abi"):
            if e.get("type") != "function":
                continue
            if e.get("stateMutability") in ("view", "pure"):
                continue  # cannot write storage
            types = [x["type"] for x in e["inputs"]]
            sig = f'{e["name"]}({",".join(types)})'
            if sig in seen:
                continue
            seen.add(sig)
            args = [arg_expr(t, i) for i, t in enumerate(types)]
            if any(a is None for a in args):
                skipped.append(sig)
                continue
            actions.append((sig, args))
    return actions, skipped


if __name__ == "__main__":
    cfg = json.load(open(sys.argv[1]))
    proxy, logic = cfg["proxy"], cfg["logic"]

    actions, skipped = collect_actions([proxy, logic])
    ranges = [(lo, hi) for _, _, lo, hi in find_overlaps(get_layout(proxy), get_layout(logic))]

    encode = []
    for a, (sig, args) in enumerate(actions):
        extra = (", " + ", ".join(args)) if args else ""
        encode.append(f'        if (a == {a}) return abi.encodeWithSignature("{sig}"{extra});')

    overlap = " || ".join(f"(pos >= {lo} && pos < {hi})" for lo, hi in ranges) or "false"
    imports = "\n".join(f'import "{p}";' for p in cfg["imports"])

    out = (TEMPLATE
           .replace("@@IMPORTS@@", imports)
           .replace("@@N@@", str(len(actions)))
           .replace("@@DEPLOY@@", cfg["deploy"])
           .replace("@@ENCODE@@", "\n".join(encode))
           .replace("@@OVERLAP@@", overlap))
    open("test/Generated.t.sol", "w").write(out)

    print(f"actions: {len(actions)}   skipped (unsupported arg types): {len(skipped)}")
    for s in skipped:
        print("   skipped", s)
    print(f"overlap ranges: {ranges}")
    print("wrote test/Generated.t.sol")